window.ACADEMY_DATA={"version":"2.5.0-curriculum-review-candidate","status":"EDUCATIONAL_DRAFT_HUMAN_REVIEW_REQUIRED","courses":[{"id":"AT-001","name_ko":"AI 수학·통계 기초","track":"AT","level":"Foundation-Advanced","prerequisites":[],"modules":[{"sequence":1,"title":"선형대수·벡터와 행렬","objective":"실습 수행 목표 — 가상 관측 3건과 특성 2개로 3×2 행렬을 작성하고 각 열의 단위를 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"확률분포와 조건부확률","objective":"실습 수행 목표 — 임의의 모수 3개를 정하고 양성예측도 TP/(TP+FP)를 계산하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"미분·경사하강법","objective":"실습 수행 목표 — L(w)=(w-2)**2를 두고 초기값 0과 학습률 0.1에서 세 단계의 w를 손으로 계산하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"손실함수와 최적화","objective":"실습 수행 목표 — 오차 [2,-1,-3]의 MAE·MSE를 계산하고 어떤 오차를 더 크게 반영하는지 설명하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"통계적 추정·신뢰구간","objective":"실습 수행 목표 — 표본수·평균·표준오차를 명시해 95% 근사 구간을 계산하고 가정을 나열하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"모델 지표의 불확실성","objective":"실습 수행 목표 — 성공 18건/20건과 180건/200건의 동일 정확도 90%라도 불확실성이 왜 다른지 설명하라.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 표본으로 평균·분산·신뢰구간의 의미 설명","common_error":"통계적 상관을 인과로 단정","deliverable":"수학적 모델링 노트","check_question":"“통계적 상관을 인과로 단정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 표본으로 평균·분산·신뢰구간의 의미 설명을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"벡터·행렬은 데이터를 수치적으로 표현하는 도구이고, 확률은 불확실성을 수량화한다. 손실함수의 최소화 결과와 통계적 일반화는 다른 개념이다.","misconception":"상관관계나 좁은 신뢰구간을 인과관계 또는 미래 성능 보장으로 해석하지 않는다."},{"id":"AT-002","name_ko":"AI를 위한 Python","track":"AT","level":"Foundation-Advanced","prerequisites":[],"modules":[{"sequence":1,"title":"자료형·함수·자료구조","objective":"실습 수행 목표 — 두 개의 합성 딕셔너리를 입력받아 ID와 온도를 검증하는 함수의 입력·반환 규약을 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"파일과 CSV·JSON 처리","objective":"실습 수행 목표 — 쉼표가 포함된 문자열·빈 값·한글을 가진 CSV 3건을 파싱한 뒤 JSON으로 변환하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"NumPy·Pandas 개념","objective":"실습 수행 목표 — 세 열 DataFrame에서 결측 비율을 계산하고 배열 길이·축·타입을 확인하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"예외·타입·로깅","objective":"실습 수행 목표 — 값 변환 함수에서 예상 예외와 예상하지 못한 예외의 처리 차이를 코드로 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"테스트와 가상환경","objective":"실습 수행 목표 — 정상·경계·오류 입력을 포함하는 세 가지 테스트와 의존성 잠금 방법을 기록하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"재현 가능한 데이터 처리","objective":"실습 수행 목표 — 원본 파일 해시·코드 버전·실행 명령·시드·출력 해시가 포함된 실행 매니페스트를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 CSV 정제 함수와 단위시험 작성","common_error":"재실행 시 데이터가 누적되는 문제 방치","deliverable":"검증된 Python 모듈","check_question":"“재실행 시 데이터가 누적되는 문제 방치”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 CSV 정제 함수와 단위시험 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"Python 실습은 입력 검증, 단위 테스트, 재현 가능한 환경, 오류 처리와 데이터 출처 기록까지 포함한다.","misconception":"노트북에서 한 번 작동한 스크립트는 배포 가능한 프로그램과 다르다."},{"id":"AT-003","name_ko":"머신러닝","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"지도·비지도학습과 문제정의","objective":"실습 수행 목표 — 문제 정의서에 예측시점·목표·개입조치·비AI 기준선을 기재하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"특성 엔지니어링","objective":"실습 수행 목표 — 두 장비군을 분리한 후 훈련에서 표준화 매개변수를 만들고 test 변환 순서를 설명하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"분류·회귀 모델","objective":"실습 수행 목표 — 평균 회귀 기준선 또는 다수 클래스 기준선과 비교해 적절한 분류·회귀 지표를 선택하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"교차검증과 그룹 분할","objective":"실습 수행 목표 — 행 무작위 분할과 그룹 분할의 ID 교집합을 계산하고 어느 목표에 적합한지 설명하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"편향·분산·과적합","objective":"실습 수행 목표 — 훈련/검증 곡선을 비교해 과적합 가설 2개와 추가 시험을 제시하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"오류분석·성능보고","objective":"실습 수행 목표 — 오류 10건의 유형·원인 가설·재검증 계획을 작성하고 최종 시험세트를 별도로 보존하라.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 학습자료로 기준모델과 그룹 분할 비교","common_error":"시험 데이터로 반복적 모델 선택","deliverable":"모델 평가 보고서","check_question":"“시험 데이터로 반복적 모델 선택”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 학습자료로 기준모델과 그룹 분할 비교을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"머신러닝의 성능은 데이터 분할의 독립성, 기준모델, 업무 비용을 반영한 평가지표로 판단한다.","misconception":"같은 개체의 반복 관측이 학습·시험 양쪽에 들어가면 과대평가가 발생할 수 있다."},{"id":"AT-004","name_ko":"딥러닝","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"텐서·자동미분","objective":"실습 수행 목표 — 한 개 가중치와 MSE 손실을 갖는 연산 그래프를 만들고 계산·미분 결과를 비교하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"MLP·CNN 기본구조","objective":"실습 수행 목표 — 간단한 MLP와 2단계 CNN을 도식화하고 입력·출력 텐서 차원을 계산하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"손실함수와 최적화","objective":"실습 수행 목표 — 두 예측 확률의 교차엔트로피를 계산하고 학습률 변화에 따른 손실 기록 방안을 제시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"정규화·드롭아웃","objective":"실습 수행 목표 — 학습·평가 모드별 드롭아웃과 정규화의 동작 차이를 표로 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"학습 곡선·성능 병목","objective":"실습 수행 목표 — 학습·검증 손실 두 곡선을 그리고 병목 측정을 위한 수치 3개를 정의하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"재현성·자원 관리","objective":"실습 수행 목표 — 두 실행의 결과 차이를 평가할 재현 로그 스키마와 메모리 장애 대응을 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"공개 예제 기반 신경망 실험계획 작성","common_error":"훈련 정확도만 보고 일반화 주장","deliverable":"학습 실험 기록","check_question":"“훈련 정확도만 보고 일반화 주장”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 공개 예제 기반 신경망 실험계획 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"딥러닝의 표현학습 능력과 데이터 요구량·과적합·학습비용의 균형을 검토한다.","misconception":"복잡한 신경망이 항상 단순한 기준모델보다 유리하지는 않다."},{"id":"AT-005","name_ko":"Transformer 아키텍처","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"토큰·임베딩·위치정보","objective":"실습 수행 목표 — 토큰화 전후 ID 수와 임베딩 shape를 기록하고 한글·영문 혼합 입력을 비교하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Self-Attention","objective":"실습 수행 목표 — Q·K·V의 shape와 causal mask 적용 전후 접근 가능한 위치를 표로 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"Multi-Head Attention","objective":"실습 수행 목표 — 임베딩 768, 헤드 12 조건의 head_dim을 계산하고 헤드 병렬 결과 결합 shape를 설명하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"Encoder·Decoder 구조","objective":"실습 수행 목표 — 가상 분류·번역·자동완성 3개 과제에 적합한 구조와 마스킹 이유를 제시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"학습·추론 계산량","objective":"실습 수행 목표 — 문맥 길이 1,024와 2,048의 n² 비율과 KV 캐시 사용 시 차이를 설명하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"문맥길이·제약·오류","objective":"실습 수행 목표 — 긴 문맥 입력과 청킹 검색의 장단점·평가 설계를 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"작은 토큰 예제로 attention 계산 검토","common_error":"Attention을 곧 설명가능한 인과관계로 단정","deliverable":"Transformer 설계 설명서","check_question":"“Attention을 곧 설명가능한 인과관계로 단정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 작은 토큰 예제로 attention 계산 검토을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"Transformer는 attention과 위치정보를 이용해 시퀀스 표현을 구성한다. 사전학습 목적과 추론 비용을 함께 이해한다.","misconception":"긴 문맥이 입력되었다는 사실과 모든 내용이 정확히 활용되었다는 것은 다르다."},{"id":"AT-006","name_ko":"LLM Engineering","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"언어모델·토큰화","objective":"실습 수행 목표 — 자연스러운 답변과 근거 있는 답변의 차이를 3개 기준으로 평가하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"프롬프트·구조화 출력","objective":"실습 수행 목표 — 업무 목적·근거 인용·금지사항·필수 필드를 가진 프롬프트와 스키마 검증 규칙을 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"컨텍스트·토큰비용","objective":"실습 수행 목표 — 일간 호출수·토큰 분포·단가를 변수로 월 비용식을 구성하고 캐시 효과의 조건을 적어라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"파인튜닝과 추론 전략","objective":"실습 수행 목표 — 형식 일관성 문제와 최신 근거 문제에 대해 파인튜닝·RAG·규칙 처리 대안을 비교하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"환각·근거·평가","objective":"실습 수행 목표 — 근거 있는 답변·근거 없는 단정·근거 부족 시 유보 3종 평가셋을 설계하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"보안·운영·버전","objective":"실습 수행 목표 — 모델 변경과 권한 우회·외부전송 실패 사례를 포함한 회귀 시험 5개를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"비공개정보 없는 규정 요약용 평가 세트 설계","common_error":"근거 없는 생성 결과를 검증된 사실로 취급","deliverable":"LLM 평가 명세","check_question":"“근거 없는 생성 결과를 검증된 사실로 취급”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 비공개정보 없는 규정 요약용 평가 세트 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"LLM 응용은 프롬프트, 도구, 구조화 출력, 인용, 실패 처리, 비용·지연을 함께 설계해야 한다.","misconception":"모델이 단정적으로 생성한 답변은 검증된 사실과 다르다."},{"id":"AT-007","name_ko":"RAG Engineering","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"문서 수집·정제","objective":"실습 수행 목표 — 3개 공개·합성 문서의 전처리 명세와 표·각주 검증 계획을 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"청킹·임베딩·색인","objective":"실습 수행 목표 — 고정 길이·조항 기반 두 가지 청킹 전략의 검색 근거 보존을 비교하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"검색·재순위화","objective":"실습 수행 목표 — 동일 질문 5개에 키워드·벡터·혼합 검색의 정답 포함률을 비교하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"인용·출처·권한 필터","objective":"실습 수행 목표 — 역할 2개·자료등급 2개를 정의하고 검색 거부·인용 위치 검증 사례를 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"검색 성능 평가","objective":"실습 수행 목표 — 다른 난이도의 질문 10개에 Recall@3, MRR을 계산하고 실패 유형을 분류하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"생성·근거 검증","objective":"실습 수행 목표 — 정답가능·근거부족·서로 모순되는 문서 질문을 각각 3건 만들고 유보 기준을 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"공개 정책문서 검색 프로토타입 평가 설계","common_error":"관련 문서를 찾지 못한 사실을 숨김","deliverable":"RAG 실험계획·평가표","check_question":"“관련 문서를 찾지 못한 사실을 숨김”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 공개 정책문서 검색 프로토타입 평가 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"RAG는 원천문서·검색·재정렬·생성·인용의 전체 경로를 시험한다. 검색 실패와 생성 실패를 구분한다.","misconception":"문서가 검색되었다고 근거가 답변을 실제로 지지한다고 볼 수 없다."},{"id":"AT-008","name_ko":"AI Agent Engineering","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"Agent와 Workflow 구분","objective":"실습 수행 목표 — 세 업무를 고정 작업과 동적 판단으로 구분하고 Agent 도입 필요성을 설명하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"도구·권한·행동계약","objective":"실습 수행 목표 — 도구 2개에 대해 입력 검증·권한·오류 결과·최대 호출수를 계약으로 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"계획·상태·메모리","objective":"실습 수행 목표 — 에이전트 상태 4개와 저장 가능한 정보·삭제 조건을 정의하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"실패·재시도·승인","objective":"실습 수행 목표 — 읽기·쓰기 작업별 최대 재시도·멱등키·사용자 승인 기준을 설계하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"Prompt Injection 대응","objective":"실습 수행 목표 — 신뢰경계를 표시하고 악성 주석·도구출력 위조·거부 시험 3개를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"에이전트 실행평가","objective":"실습 수행 목표 — 성공·복구·안전 위반·비용 지표와 중단 조건이 있는 평가표를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 교육행정 도구의 승인 워크플로 설계","common_error":"읽기 권한으로 쓰기 작업을 허용","deliverable":"Agent 권한·시험 설계","check_question":"“읽기 권한으로 쓰기 작업을 허용”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 교육행정 도구의 승인 워크플로 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"Agent는 계획·도구 호출·상태 변화·권한 경계를 가진다. 사람이 승인해야 하는 단계와 안전한 실패 경로가 필요하다.","misconception":"다단계 자동화가 성공한 것과 그 작업이 인가되었다는 것은 다르다."},{"id":"AT-009","name_ko":"Computer Vision","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"이미지와 좌표·해상도","objective":"실습 수행 목표 — 좌표 변환 전후 박스 2개의 값과 폭·높이를 계산하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"분류·탐지·분할","objective":"실습 수행 목표 — 문제 3개에 필요한 출력형식·라벨비용·평가지표를 비교하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"라벨링·데이터 증강","objective":"실습 수행 목표 — 학습 안전 증강 3개와 금지·재라벨 필요한 증강 2개를 분류하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"Precision·Recall·IoU","objective":"실습 수행 목표 — TP=8 FP=2 FN=4의 Precision·Recall과 박스 IoU 사례를 계산하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"도메인 이동·편향","objective":"실습 수행 목표 — 카메라·조도·날씨·촬영각별 평가 매트릭스를 작성하고 미측정 조합을 표시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"오류유형·검증","objective":"실습 수행 목표 — 오류 20건의 분모·유형·개선 가설·재시험 절차를 기록하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"일반 공개 이미지로 탐지 평가셋 설계","common_error":"데이터셋 성능을 현장 성능으로 일반화","deliverable":"CV 평가 카드","check_question":"“데이터셋 성능을 현장 성능으로 일반화”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 일반 공개 이미지로 탐지 평가셋 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"컴퓨터비전 평가에는 조명·가림·시점·배경 변화, 클래스별 오류와 데이터 라벨 품질을 포함한다.","misconception":"단일 공개 영상 집합의 높은 정확도를 실운용 환경으로 일반화하지 않는다."},{"id":"AT-010","name_ko":"Robotics & Physical AI","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"센서·액추에이터·제어","objective":"실습 수행 목표 — 가상 온도 제어의 센서→제어기→액추에이터 흐름과 포화·고장 사례를 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"좌표·시간 동기화","objective":"실습 수행 목표 — 센서 두 개의 좌표 변환·시계 오차·최대 허용 지연을 명세하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"인식·계획·행동","objective":"실습 수행 목표 — 인식 신뢰도 하락·계획 실패·행동 금지 세 가지 상태 전이도를 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"시뮬레이션과 실제 격차","objective":"실습 수행 목표 — 현실 차이 5개를 나열하고 시뮬레이션 가정을 검증할 시험을 제시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"안전한 평가·Fail-safe","objective":"실습 수행 목표 — 센서 단선·전원 장애·제어기 오류별 안전 상태·복구권한을 표로 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"성능·안전성 검증","objective":"실습 수행 목표 — 환경조건별 시험계획과 안전 위반 1건 발생 시 중단·조사 기준을 제시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"비작전 교육용 이동 로봇의 상태머신 설계","common_error":"시뮬레이터 성공을 실물 안전성으로 간주","deliverable":"Physical AI 안전 시험계획","check_question":"“시뮬레이터 성공을 실물 안전성으로 간주”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 비작전 교육용 이동 로봇의 상태머신 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"로보틱스 AI는 인지·추정·계획·제어·안전 인터록을 결합한다. 시뮬레이션과 현실 검증을 분리한다.","misconception":"시뮬레이터에서 안전한 행동이 현장에서 같은 안전성을 보장하지 않는다."},{"id":"AT-011","name_ko":"AI 인프라","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"CPU·GPU·메모리·스토리지","objective":"실습 수행 목표 — 모델 크기·정밀도·동시 사용자·메모리 요구사항을 구분해 산정하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"가상화·컨테이너 기초","objective":"실습 수행 목표 — VM과 컨테이너의 격리·성능·배포·보안 책임을 비교하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"워크로드·용량 추정","objective":"실습 수행 목표 — 동시요청·평균 지연·95백분위 지연·배치 크기를 포함한 용량시험을 설계하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"모델 서빙 구성","objective":"실습 수행 목표 — 버전별 모델·전처리·스키마·헬스체크와 롤백 절차를 정의하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"망 분리·아티팩트 반입","objective":"실습 수행 목표 — 패키지·모델·데이터셋별 반입 심사 체크리스트와 반려 조건을 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"비용·장애·운영","objective":"실습 수행 목표 — 온프레미스·임차 대안별 CAPEX/OPEX와 장애 복구시간을 변수로 비교하라.","learning_cycle":"실무 산출물 평가"}],"lab":"오프라인 교육용 학습환경 자원 산정","common_error":"GPU 수만으로 서비스 처리량 단정","deliverable":"인프라 용량 명세","check_question":"“GPU 수만으로 서비스 처리량 단정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 오프라인 교육용 학습환경 자원 산정을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 인프라는 계산량뿐 아니라 메모리, 저장, 네트워크, 지연, 에너지, 운영인력과 보안제약을 평가한다.","misconception":"GPU 수만으로 모델 처리량과 총소유비용을 추론하지 않는다."},{"id":"AT-012","name_ko":"MLOps","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"실험·모델 버전","objective":"실습 수행 목표 — 재현에 필요한 최소 메타데이터 8개와 실행 ID 연결 구조를 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Feature·Data Lineage","objective":"실습 수행 목표 — 학습·서빙 특성 계산의 일치성 테스트와 소스→특성 계보를 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"CI·CD·CT 구분","objective":"실습 수행 목표 — 코드 변경·데이터 변경·모델 변경 각각에 필요한 자동·수동 게이트를 제시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"배포·롤백·모니터링","objective":"실습 수행 목표 — 장애 종류별 롤백 트리거·복구 목표·사용자 영향 통보를 설계하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"드리프트·재학습 승인","objective":"실습 수행 목표 — 드리프트 지표·경보 임계값·라벨 확보·재학습 승인 순서를 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"재현성·통제","objective":"실습 수행 목표 — 생성·검토·승인·배포·중단 책임과 증거파일을 포함한 RACI를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 모델의 버전·배포 게이트 설계","common_error":"모델 파일만 기록하고 데이터 버전 누락","deliverable":"MLOps 운영 설계","check_question":"“모델 파일만 기록하고 데이터 버전 누락”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 모델의 버전·배포 게이트 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"MLOps는 데이터·모델·코드·환경의 버전 관리와 학습·평가·배포·모니터링의 검증 가능한 연계를 다룬다.","misconception":"자동 배포 파이프라인이 모델 품질의 승인까지 대신하지는 않는다."},{"id":"AT-013","name_ko":"AI Evaluation","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"문제별 평가척도","objective":"실습 수행 목표 — 세 업무 목표에 대해 지표·분모·수용 목표·측정 불가능한 항목을 표로 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"검증셋·시험셋","objective":"실습 수행 목표 — 학습·검증·최종시험 설계를 제시하고 최종시험 접근 승인 기준을 적어라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"신뢰구간·유의성","objective":"실습 수행 목표 — 부트스트랩 또는 사전 정의된 분석으로 차이의 불확실성을 보고하고 실무 최소효과를 구분하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"강건성·편향·안전","objective":"실습 수행 목표 — 정상·저해상도·소수 언어·오염 입력별 평가표와 중단조건을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"LLM 인간·자동 평가","objective":"실습 수행 목표 — 자동평가와 전문가 심사 조건을 구분하고 불일치 조정 절차를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"TEV&V·Go/No-Go","objective":"실습 수행 목표 — 요구사항→시험ID→관측결과→잔여위험→승인자를 연결한 게이트표를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"AI 사업 수용기준 및 오류 분석표 작성","common_error":"한 지표로 품질·안전 모두 합격 처리","deliverable":"AI TEV&V 평가계획","check_question":"“한 지표로 품질·안전 모두 합격 처리”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, AI 사업 수용기준 및 오류 분석표 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 평가는 문제 정의에 맞춘 지표·시험셋·실패 분석·불확실성·인간 검토를 포함한다.","misconception":"정확도 하나로 안전성·공정성·신뢰성을 대체하지 않는다."},{"id":"AT-014","name_ko":"AI Security","track":"AT","level":"Foundation-Advanced","prerequisites":["AT-001","AT-002"],"modules":[{"sequence":1,"title":"AI 위협 모델","objective":"실습 수행 목표 — 자산·위협·영향·통제·검증 5열의 위험표를 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"데이터 오염·누출","objective":"실습 수행 목표 — 합성 데이터 무결성·권한검사와 오염 의심 파일 격리 절차를 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"Prompt Injection·도구권한","objective":"실습 수행 목표 — 악성 문서·악성 질의·위조된 도구출력 각각에 대해 차단 경계를 시험하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"모델·API 접근통제","objective":"실습 수행 목표 — 키 노출·권한 우회·요청 폭주에 대한 부정시험 3개와 로그 필드를 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"공급망·모델 아티팩트","objective":"실습 수행 목표 — 외부 모델 파일의 반입 승인표에 아티팩트 해시·버전·권리·취약성을 포함하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"보안시험·사고대응","objective":"실습 수행 목표 — 사고 1건에 대한 탐지→차단→증거보존→복구→재승인 절차를 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 RAG 환경 권한 우회 시나리오 차단 설계","common_error":"프롬프트만으로 접근통제 대체","deliverable":"AI 보안 통제표","check_question":"“프롬프트만으로 접근통제 대체”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 RAG 환경 권한 우회 시나리오 차단 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.nist.gov/itl/ai-risk-management-framework","https://developers.google.com/machine-learning/crash-course/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"모델과 데이터 공급망, 프롬프트 인젝션, 권한 오용, 모델 출력 검증을 위협 모델과 연결한다.","misconception":"RAG 자료나 도구 응답을 신뢰할 수 있는 시스템 지시로 승격하지 않는다."},{"id":"DF-001","name_ko":"데이터 기초","track":"DF","level":"Foundation-Advanced","prerequisites":[],"modules":[{"sequence":1,"title":"데이터·정보·지식 구분","objective":"실습 수행 목표 — ‘재고 5’라는 원시 값을 데이터→정보→지식 수준으로 각각 재작성하세요. 품목·단위·기준 시각·원천과 의사결정에 필요한 추가 근거를 명시하세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"구조·비구조·이벤트 데이터","objective":"실습 수행 목표 — 가상의 점검 보고서(PDF), 장비 목록(CSV), 정비 알림(JSON)에서 각각 추출할 핵심 메타데이터 3개와 중복을 방지할 식별 기준을 제시하세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"데이터 생애주기","objective":"실습 수행 목표 — 합성 센서 데이터의 수집·검증·저장·공유·폐기 단계별 담당 주체와 1개 이상의 확인 증거를 표로 작성하세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"ID·시간·단위·NULL","objective":"실습 수행 목표 — 장비 표본 3건의 ID·측정 시각·시간대·단위·NULL 처리 규칙을 설계하고, 잘못 결합했을 때 생길 문제 2가지를 작성하세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"데이터 품질 차원","objective":"실습 수행 목표 — 20건의 가상 데이터 중 누락 3건과 잘못된 코드 2건을 대상으로 품질 규칙·분모·계산 결과·처리 조치를 작성하세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"데이터 가치·보안·출처","objective":"실습 수행 목표 — 실습용 합성 데이터셋 하나의 데이터 자산카드를 만들고, 업무 목적·출처·권리·접근·품질·보존·이용 제한을 각각 한 줄 이상 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 장비·교육 데이터 용어사전 작성","common_error":"필드명 같음이 곧 의미 동일함이라 단정","deliverable":"기초 데이터 자산카드","check_question":"“필드명 같음이 곧 의미 동일함이라 단정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 장비·교육 데이터 용어사전 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"데이터는 측정·기록·식별·시간·출처·사용 목적을 함께 가진다. 수치와 업무 의미의 관계를 명시한다.","misconception":"동일한 칼럼명이나 값 형식만으로 데이터의 업무적 동일성을 단정하지 않는다."},{"id":"DF-002","name_ko":"SQL·데이터베이스","track":"DF","level":"Foundation-Advanced","prerequisites":[],"modules":[{"sequence":1,"title":"관계형 모델·키·제약","objective":"실습 수행 목표 — 장비·정비·부품 3개 테이블의 PK와 FK를 설계하고 참조 무결성 위반 한 건을 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"SELECT·JOIN·GROUP BY","objective":"실습 수행 목표 — 테이블 두 개를 JOIN하고 장비 수와 정비 건수를 각각 조회하는 SQL을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"CTE·윈도함수","objective":"실습 수행 목표 — 장비별 최신 정비 1건을 추출하는 CTE와 ROW_NUMBER 쿼리의 결정적 정렬 규칙을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"정규화·트랜잭션","objective":"실습 수행 목표 — 정비 기록 추가와 재고 수량 변경을 하나의 트랜잭션으로 묶고 실패시 롤백 사례를 설명하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"인덱스·실행계획","objective":"실습 수행 목표 — 가상 데이터에서 WHERE·ORDER BY에 맞는 복합 인덱스를 정의하고 EXPLAIN 전후를 비교하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"백업·복구·접근통제","objective":"실습 수행 목표 — 복구 시나리오에 RPO·RTO 목표를 제시하고 성공 판정 쿼리 및 접근 권한을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 정비 DB를 생성하여 관계 질의 작성","common_error":"JOIN 중복으로 집계가 부풀려짐","deliverable":"SQL·실행시험 보고서","check_question":"“JOIN 중복으로 집계가 부풀려짐”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 정비 DB를 생성하여 관계 질의 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"관계형 모델의 키와 제약조건, SQL JOIN과 집계, 트랜잭션 경계를 이해해야 데이터 변환의 결과를 검증할 수 있다.","misconception":"조인 전후의 행 수가 같아도 잘못 연결된 레코드가 존재할 수 있다."},{"id":"DF-003","name_ko":"데이터 모델링","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"개념·논리·물리 모델","objective":"실습 수행 목표 — 개념→논리→물리 모델마다 바뀌는 항목 3개를 표로 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"ERD·기수·선택성","objective":"실습 수행 목표 — 장비·정비·부품의 기수와 필수 관계를 ERD로 표시하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"함수 종속성과 정규화","objective":"실습 수행 목표 — 장비 명칭을 분리한 스키마와 정비ID→장비ID, 장비ID→장비명 종속성을 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"Fact Grain·Dimensional Model","objective":"실습 수행 목표 — 두 팩트의 grain과 재고 수량 집계 가능·불가능 조건을 적어라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"SCD·시간 모델","objective":"실습 수행 목표 — valid_from·valid_to가 겹치지 않는 Type 2 차원 설계와 사건 시점 조인을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"스키마 변경·식별자","objective":"실습 수행 목표 — 스키마 v1→v2 열 변경과 원천 ID 충돌 테스트를 제시하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"장비·정비 관계모델과 검증쿼리 설계","common_error":"대리키가 업무 유일성을 보장한다고 오해","deliverable":"ERD·데이터 사전","check_question":"“대리키가 업무 유일성을 보장한다고 오해”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 장비·정비 관계모델과 검증쿼리 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"개념·논리·물리 모델을 분리하고, 사실 테이블의 grain과 시간·식별자 의미를 먼저 고정한다.","misconception":"대체키 사용이 업무상 유일성·정합성 검증을 대체하지 않는다."},{"id":"DF-004","name_ko":"ETL/ELT 엔지니어링","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"ETL·ELT·Hybrid","objective":"실습 수행 목표 — ETL과 ELT 각각의 변환 위치·권한·실패 지점을 도식화하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Batch·Incremental·CDC","objective":"실습 수행 목표 — 변경·삭제·중복을 모두 수집하는 증분 커서 전략을 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"변환·멱등성","objective":"실습 수행 목표 — 동일 입력을 두 번 처리해 행 수와 합계가 변하지 않음을 검사하는 테스트를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"오류·Quarantine·Retry","objective":"실습 수행 목표 — 오류 유형을 영구·일시로 나누고 재시도 횟수·대기·격리 기준을 정의하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"오케스트레이션·관측성","objective":"실습 수행 목표 — 파이프라인 DAG와 각 단계 성공·실패 기준, 경보 조건을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"라인리지·데이터 계약","objective":"실습 수행 목표 — 데이터 계약에 필드·허용값·지연 SLO·소유자·버전을 명시하고 변경 시험을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 데이터의 재실행 안전 파이프라인 구현","common_error":"updated_at 하나로 누락 방지 보장 주장","deliverable":"파이프라인·재처리 증거","check_question":"“updated_at 하나로 누락 방지 보장 주장”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 데이터의 재실행 안전 파이프라인 구현을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"ETL/ELT 파이프라인은 원본 보존, 변환 이력, 재실행 멱등성, 지연 데이터와 삭제를 처리해야 한다.","misconception":"updated_at만으로 증분 적재의 완전성을 보장할 수 없다."},{"id":"DF-005","name_ko":"Data Lakehouse","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"Lake·Warehouse·Lakehouse","objective":"실습 수행 목표 — 같은 자료가 Lake, Warehouse, Lakehouse에 저장될 때 스키마·성능·운영 위험을 비교하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Parquet·컬럼 저장","objective":"실습 수행 목표 — 같은 데이터 CSV·Parquet의 파일 크기와 열 선택 읽기 특성을 실측 비교하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"테이블 포맷·ACID","objective":"실습 수행 목표 — 파일 형식과 Iceberg형 테이블 포맷의 역할·커밋 경계를 구분하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"카탈로그·스냅샷","objective":"실습 수행 목표 — 카탈로그에 owner·schema·snapshot ID·보존 정책·이용조건을 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"파티션·Compaction","objective":"실습 수행 목표 — 일자·장비별 파티션 대안과 작은 파일 수를 비교하는 실험계획을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"보안·자원·성능","objective":"실습 수행 목표 — 데이터 경로별 권한·감사 기록과 월간 저장·스캔 비용 항목을 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"CSV와 Parquet 집계 차이·조건 검사","common_error":"파일 형식과 테이블 형식을 혼동","deliverable":"Lakehouse 대안 비교","check_question":"“파일 형식과 테이블 형식을 혼동”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, CSV와 Parquet 집계 차이·조건 검사을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"레이크하우스는 파일 포맷, 테이블 메타데이터, 처리 엔진, 카탈로그의 역할을 구분해야 한다.","misconception":"Parquet 파일 자체가 다중 테이블 트랜잭션을 보장하는 것은 아니다."},{"id":"DF-006","name_ko":"Data Quality","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"정확성·완전성·유효성","objective":"실습 수행 목표 — 품질 차원별 평가 규칙과 분모를 정의하고 확인되지 않은 정확성은 미측정으로 표시하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Profiling·규칙·측정","objective":"실습 수행 목표 — Profile 결과에서 가설 3개와 이를 검증할 명시적 규칙 3개를 만들라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"결측·이상치·중복","objective":"실습 수행 목표 — 결측·이상·중복 각각의 처리 전후 행 수와 원본 보존 조치를 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"오류 격리·재처리","objective":"실습 수행 목표 — Quarantine 레코드에 issue_id·rule_id·source_hash·retry_history 필드를 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"품질 지표·Observability","objective":"실습 수행 목표 — 중요도별 SLO와 경보·차단 조건을 표로 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"RCA·품질 개선","objective":"실습 수행 목표 — 5-Why 또는 인과도를 이용해 원인·교정·재발방지·검증 결과를 정리하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 오류 주입 4종 자동 탐지","common_error":"검증 불가능한 차원에 100점 부여","deliverable":"DQ Report·Rules","check_question":"“검증 불가능한 차원에 100점 부여”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 오류 주입 4종 자동 탐지을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"품질은 정확성·완전성·일관성·유일성·적시성 등 목적별 기준과 측정 방법을 정의한다.","misconception":"통과율 평균으로 핵심 보안·무결성 위반을 가리면 안 된다."},{"id":"DF-007","name_ko":"Metadata·Ontology","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"카탈로그·데이터사전","objective":"실습 수행 목표 — 가상의 데이터사전에서 열 5개에 설명·타입·NULL 허용·코드목록·담당자를 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Glossary·Data Contract","objective":"실습 수행 목표 — 가용률 용어정의와 데이터를 공급할 API 계약의 필수·선택 필드를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"RDF·RDFS·OWL","objective":"실습 수행 목표 — 트리플 세 개를 Turtle로 표현하고 각 URI와 리터럴의 역할을 설명하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"SKOS·DCAT·PROV","objective":"실습 수행 목표 — 가상 카탈로그에 DCAT 배포 정보와 PROV 생성활동 한 건을 연결하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"SHACL 검증","objective":"실습 수행 목표 — 정비 이벤트에서 필수 ID와 선택 부품 관계를 구분한 SHACL Shape를 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"온톨로지 관리·버전","objective":"실습 수행 목표 — 온톨로지 v1과 v2의 달라진 관계·쿼리 영향·롤백 계획을 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 데이터 용어·RDF 메타데이터 작성","common_error":"OWL 추론과 SHACL 검증 혼동","deliverable":"Glossary·Ontology Draft","check_question":"“OWL 추론과 SHACL 검증 혼동”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 데이터 용어·RDF 메타데이터 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"기술·업무·운영 메타데이터를 연결하고 온톨로지의 개체·관계·제약을 업무 전문가와 함께 정의한다.","misconception":"OWL의 추론과 SHACL의 검증은 서로 다른 목적을 가진다."},{"id":"DF-008","name_ko":"Data Integration","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"Consolidation·Federation","objective":"실습 수행 목표 — 지연·보안·데이터 최신성·원천 부하·유지비를 평가 표로 만든다. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"API·CDC·Event 통합","objective":"실습 수행 목표 — 각 통합 수단에 idempotency key·지연·오류 복구 기준을 명시하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"Canonical Model·Identity","objective":"실습 수행 목표 — 전역 식별자와 원천 식별자·매핑 신뢰상태를 구분해 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"Schema Registry·Contract","objective":"실습 수행 목표 — 필드 추가·이름 변경·코드 의미 변경을 별도 호환 테스트로 만들라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"Outbox·Saga·Reconcile","objective":"실습 수행 목표 — Outbox·Saga·Reconciliation이 각각 해결할 실패 유형과 책임자를 비교하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"권한·감사·운영","objective":"실습 수행 목표 — 원천 권한과 통합 권한 간 정책 매핑표·거부시험·감사기록을 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"서로 다른 식별자의 가상 장비 연결","common_error":"같은 이름 필드를 동일 개체로 자동 병합","deliverable":"통합 설계·정합성 보고","check_question":"“같은 이름 필드를 동일 개체로 자동 병합”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 서로 다른 식별자의 가상 장비 연결을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"통합은 원천 간 구조뿐 아니라 식별자·업무 의미·시간·권한·재처리·충돌 해결을 포함한다.","misconception":"ETL 작업 종료 성공은 전체 업무 데이터의 정합성을 보장하지 않는다."},{"id":"DF-009","name_ko":"Streaming Architecture","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"Event Time·Processing Time","objective":"실습 수행 목표 — event_time과 ingestion_time을 가진 샘플 5건을 만들고 시간차를 계산하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Kafka Topic·Partition","objective":"실습 수행 목표 — 파티션 3개, 소비자 4개인 사례에서 순서·처리 병렬성 제약을 설명하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"Window·Watermark","objective":"실습 수행 목표 — 지연 허용 2분/10분 두 정책의 결과 정확성·지연 차이를 비교하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"State·Checkpoint","objective":"실습 수행 목표 — 장애 직전·직후 상태와 입력 오프셋을 기록하는 복구 시나리오를 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"At-least-once·재처리","objective":"실습 수행 목표 — 중복 이벤트 10건을 포함한 입력으로 sink 중복·오프셋 재처리를 검증하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"Backpressure·관측성","objective":"실습 수행 목표 — lag 추세를 계산하고 병목·처리율·완화 방안을 분리해 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 센서 이벤트의 지연·중복 시험","common_error":"Kafka 전체 파티션 전역 순서 가정","deliverable":"Streaming 검증보고","check_question":"“Kafka 전체 파티션 전역 순서 가정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 센서 이벤트의 지연·중복 시험을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"이벤트 시간, Watermark, Window, 상태, Checkpoint, Replay의 적용 범위를 설계한다.","misconception":"브로커가 저장했다고 최종 수신 시스템에서 exactly-once 효과가 보장되지는 않는다."},{"id":"DF-010","name_ko":"Knowledge Graph","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-007"],"modules":[{"sequence":1,"title":"Competency Questions","objective":"실습 수행 목표 — 업무 질문 3개와 각각 필요한 관계 경로·출력 컬럼을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"RDF·Property Graph","objective":"실습 수행 목표 — 동일 업무질문을 두 그래프 형태로 설계하고 쿼리 언어·ID 정책을 비교하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"CSV→RDF 매핑","objective":"실습 수행 목표 — 열 4개에 대한 URI 템플릿과 값 변환·NULL 처리 규칙을 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"SPARQL 관계질의","objective":"실습 수행 목표 — SELECT와 OPTIONAL을 포함한 SPARQL 질의로 부품 미사용 정비도 반환하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"OWL 추론·SHACL 검증","objective":"실습 수행 목표 — 장비의 class 추론 예제와 정비 event_id 필수 Shape 하나를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"GraphRAG 평가·접근권한","objective":"실습 수행 목표 — 질문 10개에 대해 관계 검색·근거·권한필터·거부 사례를 평가 계획으로 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"장비·정비·부품 그래프와 질문 세트","common_error":"owl:sameAs를 단순 유사성에 적용","deliverable":"KG·Query·검증보고","check_question":"“owl:sameAs를 단순 유사성에 적용”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 장비·정비·부품 그래프와 질문 세트을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"그래프 모델은 실제 업무 질문과 출처 추적 요구를 기준으로 구성하고 질의·추론·제약 검증을 구별한다.","misconception":"그래프의 관련성을 owl:sameAs와 같은 강한 동일성으로 오용하지 않는다."},{"id":"DF-011","name_ko":"Data Governance","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"정책·책임·권한","objective":"실습 수행 목표 — 데이터 정책 하나를 대상으로 결정권자·실행·감사 역할을 표로 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Data Owner·Steward","objective":"실습 수행 목표 — 원천 데이터 오류 정정·권한 승인·용어 변경 책임을 Owner·Steward·운영자별로 나눠라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"RACI·표준·용어","objective":"실습 수행 목표 — 상태 코드 변경 절차에 RACI와 승인 전후 테스트를 붙여라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"Data Product·SLO","objective":"실습 수행 목표 — 사용자 2개 업무·스키마·SLO·오류 대응을 포함한 제품 계약서를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"정책 KPI·성숙도","objective":"실습 수행 목표 — 정책 준수와 업무 효과를 각각 나타내는 KPI 2개와 증거 수집 절차를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"예외·이행·감사","objective":"실습 수행 목표 — 예외 신청서에 근거·유효기간·완화통제·재승인 조건을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"가상 데이터 책임·표준체계 수립","common_error":"기술운영자가 업무의미도 임의 승인","deliverable":"거버넌스 헌장","check_question":"“기술운영자가 업무의미도 임의 승인”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 가상 데이터 책임·표준체계 수립을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"거버넌스는 의사결정 권한·책임·정책·품질·성과지표의 운영체계다.","misconception":"정책 문서가 존재한다는 이유만으로 실행이나 성과를 주장하지 않는다."},{"id":"DF-012","name_ko":"Data Security","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"데이터 등급·분류","objective":"실습 수행 목표 — 가상 자료 5개에 대해 공개 여부·취급 근거·접근 주체를 분류하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"RBAC·ABAC·최소권한","objective":"실습 수행 목표 — 역할×데이터등급×업무목적별 허용/거부 정책과 반례 3개를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"암호화·키·비밀정보","objective":"실습 수행 목표 — 키 발급·회전·폐기·복구 책임을 포함한 가상 키 수명주기표를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"감사·로그·반출통제","objective":"실습 수행 목표 — 접근 승인/거부와 파일 반출을 구분한 로그 필드 및 보존조건을 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"위협모델·공급망","objective":"실습 수행 목표 — 데이터 수집→전처리→학습 경로의 신뢰경계 3개와 위협·통제를 기록하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"AI·RAG 데이터 보안","objective":"실습 수행 목표 — 검색 전 권한 필터·문서 신뢰도·출력 검사를 포함한 RAG 보안 시험표를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"가상 데이터 제품 접근 정책 부정시험","common_error":"암호화만으로 전체 보안 완성 간주","deliverable":"보안 위험·시험표","check_question":"“암호화만으로 전체 보안 완성 간주”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 가상 데이터 제품 접근 정책 부정시험을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"데이터 수집부터 공유·백업·로그·폐기까지 분류·접근·암호화·감사와 최소 권한을 설계한다.","misconception":"가명처리와 익명화를 혼동하거나 운영 로그의 민감정보를 간과하지 않는다."},{"id":"DF-013","name_ko":"AI Training Dataset","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-001","DF-002"],"modules":[{"sequence":1,"title":"데이터 요구·원천 권리","objective":"실습 수행 목표 — 데이터 요구조건과 원천 권리검토 체크리스트를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"라벨·정답 기준","objective":"실습 수행 목표 — 라벨 정의서와 경계사례 5개, 검수자 의견 차이 해결 절차를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"정제·결측·대표성","objective":"실습 수행 목표 — 결측 처리 방법 2개와 그룹별 대표성 평가표를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"Group·Temporal Split","objective":"실습 수행 목표 — 무작위 행 분할과 장비 그룹 분할의 겹침 여부를 코드로 확인하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"데이터 누출·편향","objective":"실습 수행 목표 — 누출 지점 3개를 찾고 train-only 처리·그룹 성능평가를 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"Dataset Card·Manifest","objective":"실습 수행 목표 — 카드와 매니페스트에 출처·사용권·품질·분할·한계·파일 해시를 연결하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"합성 데이터 Train/Test Group Split 검증","common_error":"한 개체의 반복 관측을 무작위 혼합","deliverable":"학습데이터 Release Package","check_question":"“한 개체의 반복 관측을 무작위 혼합”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 합성 데이터 Train/Test Group Split 검증을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 데이터는 과제·라벨·사용권·표본 독립성·대표성·원천 추적을 기준으로 평가한다.","misconception":"랜덤 분할만으로 시계열·개체·기관별 평가 누출이 제거되지는 않는다."},{"id":"DF-014","name_ko":"Defense Data Architecture","track":"DF","level":"Foundation-Advanced","prerequisites":["DF-004","DF-006","DF-008","DF-011","DF-012"],"modules":[{"sequence":1,"title":"요구사항·AS-IS","objective":"실습 수행 목표 — AS-IS 흐름도에 원천·전송·보존·품질·권한·소유자 6개 항목을 표시하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"Data Domain·표준","objective":"실습 수행 목표 — 도메인 책임·공통 필드·식별자 매핑의 계약서를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"Target Architecture","objective":"실습 수행 목표 — 수집→표준화→품질→카탈로그→권한→서비스의 목표 구성도와 주체를 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"통합·품질·보안","objective":"실습 수행 목표 — 두 원천의 결합 실패·권한 거부·품질 오류를 포함한 수용시험을 설계하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"대안·비용·로드맵","objective":"실습 수행 목표 — 세 대안의 비용 항목·리스크·의존성·단계별 중단 기준을 표로 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"TEV&V·승인 경계","objective":"실습 수행 목표 — 요구조건→시험→증거→잔여위험→승인 주체를 연결한 추적행렬을 작성하라. 출력·검증 근거와 적용 한계도 함께 적으세요.","learning_cycle":"실무 산출물 평가"}],"lab":"교육용 통합 데이터 아키텍처 설계","common_error":"미확인 현황을 사실로 단정","deliverable":"EA·이행·검증 계획","check_question":"“미확인 현황을 사실로 단정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 교육용 통합 데이터 아키텍처 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000273654","https://www.w3.org/TR/shacl/","https://www.postgresql.org/docs/"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"업무 목적과 AS-IS 근거에서 출발해 데이터·통합·운영·보안·이행 아키텍처를 연결한다.","misconception":"현황자료 없이 실제 조직의 시스템 구조나 절감 효과를 확정하지 않는다."},{"id":"SP-001","name_ko":"국방 AI 정책","track":"SP","level":"Foundation-Advanced","prerequisites":[],"modules":[{"sequence":1,"title":"국내 법령·훈령 조사","objective":"실습 수행 목표 — 가상의 사업 A에 관련 법률·훈령·내부규정·실행지침의 확인 체크리스트를 만들고 확인할 수 없는 조항을 별도 표시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"국방 AI 전략과 제한","objective":"실습 수행 목표 — AI 전략의 목표 1개를 가상 사업 요구사항·위험·성과지표와 연결하는 정책 정합성 표를 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"민·관·군 협력","objective":"실습 수행 목표 — 가상 협력 협약서에 데이터 소유, 제공권한, 접근로그, 재사용, 결과물 권리, 사고통보 항목을 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"데이터·AI 조직 책임","objective":"실습 수행 목표 — 가상 RACI를 만들어 데이터 정정·모델 업데이트·사용 중단 상황의 승인권자와 수행자를 구분하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"정책 간 충돌·해석","objective":"실습 수행 목표 — 가상의 두 지침을 대상으로 상충 조항표와 적용대상·유효일·처리기관·잠정조치를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"정책 이행 KPI","objective":"실습 수행 목표 — 지표 3개에 대해 산식·분모·원천·기준값 미확정 상태·책임자·보고주기를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"공개 훈령 기반 교육용 정책 맵","common_error":"타국 정책을 국내 의무규정으로 기술","deliverable":"정책근거 대조표","check_question":"“타국 정책을 국내 의무규정으로 기술”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 공개 훈령 기반 교육용 정책 맵을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"국방 AI 정책 분석은 법령·훈령의 권한과 실제 사업 목표·범위를 구분하고 적용 시점·개정 이력을 확인한다.","misconception":"국제 지침을 국내 군의 의무 규정으로 직접 치환하지 않는다."},{"id":"SP-002","name_ko":"군 업무 문제 분석","track":"SP","level":"Foundation-Advanced","prerequisites":[],"modules":[{"sequence":1,"title":"업무 프로세스 정의","objective":"실습 수행 목표 — 프로세스 5단계의 시작·종료 조건, 담당, 입력·출력, 병목 가설을 텍스트 흐름도로 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"현상과 근본 원인","objective":"실습 수행 목표 — 5 Whys와 원인-결과도를 만들어 원인 가설 3개, 반증 가능 관측값 1개씩을 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"이해관계자·업무 인터뷰","objective":"실습 수행 목표 — 서로 다른 역할 4개에 대한 인터뷰 질문과 실제로 확인해야 할 문서·화면·업무 사례를 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"AS-IS·병목 분석","objective":"실습 수행 목표 — 현행 단계별 처리시간·대기시간·재작업률 표를 만들고 제거해도 되는 단계와 필요한 통제 단계를 구분하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"측정 가능한 문제·KPI","objective":"실습 수행 목표 — 현행 문제를 한 문장으로 정의하고 2개 KPI의 분모·측정 방법·목표의 승인 상태를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"기술 도입 전 대안","objective":"실습 수행 목표 — AI 없는 개선안 2개와 AI 대안 1개를 동일한 KPI·비용항목·보안조건으로 비교하라.","learning_cycle":"실무 산출물 평가"}],"lab":"가상 교육행정 병목을 원인 분석","common_error":"원인을 확인하기 전에 AI로 해결 확정","deliverable":"문제정의서","check_question":"“원인을 확인하기 전에 AI로 해결 확정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 가상 교육행정 병목을 원인 분석을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"업무 문제를 관찰된 현상·원인·영향·기준선으로 구분하고 비AI 대안도 함께 검토한다.","misconception":"AI 도입 자체를 문제 해결의 목표로 설정하지 않는다."},{"id":"SP-003","name_ko":"AI 활용사례 발굴","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"활용사례 탐색","objective":"실습 수행 목표 — 3개 활용후보 각각에 사용자의 업무 흐름·입력권한·결과 검토자를 적어 Use Case Canvas를 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"업무 데이터·AI 적합성","objective":"실습 수행 목표 — 한 활용사례의 규칙기반·통계모델·생성형 AI 적합성 판정표와 데이터 요구조건을 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"가치·위험·난이도","objective":"실습 수행 목표 — 후보 2개의 가치·실패영향·구현난이도·데이터권리를 1~5 척도로 정의하고 민감도 분석하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"대안·중복사업 검토","objective":"실습 수행 목표 — 기존 기능 재사용·상용서비스·신규개발 3개 대안의 장단점과 중복 가능성을 기록하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"우선순위 포트폴리오","objective":"실습 수행 목표 — 후보 3개의 가중치·근거·미해결 위험·선행조건·우선순위 변화 시나리오를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"실증 대상 선정","objective":"실습 수행 목표 — 실증의 범위·평가셋·중단조건·참여자·확대 승인 기준을 정의하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"후보 5개를 근거기반 필터링","common_error":"기술 가능성을 곧 도입 필요성으로 오인","deliverable":"활용사례 평가표","check_question":"“기술 가능성을 곧 도입 필요성으로 오인”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 후보 5개를 근거기반 필터링을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 활용사례는 사용자·업무 결정·정답 근거·입력 데이터·오류 비용을 연결해 발굴한다.","misconception":"단순 아이디어 수가 실제 사업 타당성을 뜻하지 않는다."},{"id":"SP-004","name_ko":"요구사항 공학","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"이해관계자 요구","objective":"실습 수행 목표 — 이해관계자 진술 3개를 기능 요구·비기능 요구·수용기준으로 전환하는 표를 만들라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"기능·비기능 요구","objective":"실습 수행 목표 — 기능 3개와 비기능 3개에 대해 시험 입력·환경·관측값·합격 기준을 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"데이터·보안 요구","objective":"실습 수행 목표 — 역할별 데이터 접근행렬을 만들고 최소권한·접근 거부·감사 로그의 시험 사례를 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"수용기준·추적행렬","objective":"실습 수행 목표 — 요구 5개에 대해 RTM을 작성하고 목적 없는 시험, 시험 없는 요구를 각각 탐지하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"변경·형상 관리","objective":"실습 수행 목표 — 변경요청서에 사유·영향·대안·승인권자·기준선 수정이력을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"조달·시험과 연결","objective":"실습 수행 목표 — 요구서의 3개 기능을 계약 납품물·시험증거·하자조치로 연결한 표를 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"측정 가능한 AI 요구사항 15개 작성","common_error":"정확도 높음 등 모호한 표현","deliverable":"SRS·RTM","check_question":"“정확도 높음 등 모호한 표현”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 측정 가능한 AI 요구사항 15개 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"요구사항은 측정·시험 가능한 형태로 작성하고 기능·품질·보안·운영 요구를 추적 가능하게 관리한다.","misconception":"“빠르고 정확해야 한다”와 같은 문장은 독립적인 검수기준이 아니다."},{"id":"SP-005","name_ko":"AI 사업기획","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"사업 목표·문제 정의","objective":"실습 수행 목표 — 문제 정의서에 대상 사용자, 실패 현상, 기준선 측정 계획, 성공 기준, 범위 외 항목을 기록하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"AS-IS/TO-BE","objective":"실습 수행 목표 — 현행과 개선 프로세스 각각의 단계·담당·필수승인·실패 복구 경로를 도식화하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"AI·데이터 타당성","objective":"실습 수행 목표 — 데이터 요구명세와 품질검증 항목, 불충분한 경우의 대체 계획을 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"대안·개발 범위","objective":"실습 수행 목표 — MVP 기능 3개와 단계별 제외기능 3개를 정하고 범위 변경 조건을 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"운영·보안·비용","objective":"실습 수행 목표 — 비용 계정별 산출근거와 누락 위험, 보안통제·운영주체를 표시한 비용표를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"사업계획서·결정안","objective":"실습 수행 목표 — 14항목 사업계획서를 작성하고 각 핵심 주장에 데이터 출처 또는 검증 계획을 붙여라.","learning_cycle":"실무 산출물 평가"}],"lab":"14항목 AI 사업계획서 작성","common_error":"성능·비용 근거 없이 효과 확정","deliverable":"AI Business Case","check_question":"“성능·비용 근거 없이 효과 확정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 14항목 AI 사업계획서 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"사업계획은 문제·목표·데이터·기술·대안·예산·위험·TEV&V·운영·이행계획을 같은 근거로 연결한다.","misconception":"제안서 분량과 실행 가능한 사업 설계의 품질은 다르다."},{"id":"SP-006","name_ko":"타당성 분석","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"기술 성숙도·한계","objective":"실습 수행 목표 — 기능·성능·연계·안정성 항목별 현재 근거와 추가 실증 필요조건을 기록하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"데이터 확보·품질","objective":"실습 수행 목표 — 원천별 접근 승인·품질·라벨·대표성·보안 요구·대체전략을 점검표로 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"조직·운영 가능성","objective":"실습 수행 목표 — 운영조직 RACI와 교대·비상·교육·유지보수 계약 항목을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"보안·법률 적합성","objective":"실습 수행 목표 — 보안·개인정보·사용권 확인 문서, 미해결 위험과 승인 조건을 검토표에 기록하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"대안·민감도","objective":"실습 수행 목표 — 대안별 필수 기능과 비용 변수의 범위를 정의해 민감도표를 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"Go/No-Go","objective":"실습 수행 목표 — 통과·조건부·보류·중단 네 가지 판정상태와 사전 정의 증빙을 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"가상 AI 사업 타당성 표 작성","common_error":"기술 시험이 정책 승인을 대체한다고 오인","deliverable":"Feasibility Report","check_question":"“기술 시험이 정책 승인을 대체한다고 오인”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 가상 AI 사업 타당성 표 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"타당성은 데이터 접근 가능성, 기술 검증, 보안·제도 적합성, 비용과 운영 지속성을 구분해 판단한다.","misconception":"시연 성공이 실사용 효과나 전체 도입 타당성을 입증하지 않는다."},{"id":"SP-007","name_ko":"비용·투자 분석","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"CAPEX·OPEX·TCO","objective":"실습 수행 목표 — 비용항목을 초기·연간·변동비로 나누고 기간 3년의 TCO 산식을 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"구축·전환 비용","objective":"실습 수행 목표 — 이행 단계별 인력투입·도구·시험비·병행운영 기간을 계산하는 표를 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"클라우드·온프레 대안","objective":"실습 수행 목표 — 동일 목표 응답시간·가용성·데이터 규정하에 두 대안의 비용항목과 비가격 위험을 비교하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"예산 제약·불확실성","objective":"실습 수행 목표 — 필수·선택 비용으로 분리하고 상·중·하 가격 시나리오의 예산 초과 대응책을 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"효과측정·민감도","objective":"실습 수행 목표 — 효과 KPI 2개에 대하여 기준선·처리건수·비용 전환 근거·불확실성 범위를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"투자안 비교","objective":"실습 수행 목표 — 의사결정 매트릭스에 정량 비용과 정성 위험을 분리해 작성하고 결론을 바꾸는 가정을 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"비용 근거·단위와 범위 정의","common_error":"예상 절감률 임의 작성","deliverable":"Cost Model·Assumptions","check_question":"“예상 절감률 임의 작성”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 비용 근거·단위와 범위 정의을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"TCO는 구축비뿐 아니라 라이선스·연산·데이터·보안·운영·교체·폐기까지 포함한다.","misconception":"측정하지 않은 절감률·편익을 검증된 경제효과로 보고하지 않는다."},{"id":"SP-008","name_ko":"AI 획득·계약","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"요구기능·시험가능성","objective":"실습 수행 목표 — 요구기능 4개를 시험 입력·산출물·판정 방법과 연결하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"기술사양·성능기준","objective":"실습 수행 목표 — 성능기준의 모집단·분모·부하·분위수·실패 처리 기준을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"데이터·IP·라이선스","objective":"실습 수행 목표 — 데이터·모델·코드·산출물별 권리자·허용행위·제한·계약 종료 후 처리를 표로 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"공급망·보안조건","objective":"실습 수행 목표 — 공급자 보안 요구서에 SBOM·취약점 패치기한·반입 검증·비밀관리 항목을 포함하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"검수·대금·유지보수","objective":"실습 수행 목표 — 납품물 목록에 시험증거·수용판정·재시험·하자보수 책임을 연결하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"변경·책임·종료조건","objective":"실습 수행 목표 — 계약 종료 체크리스트에 데이터·키·코드·라이선스·담당자·검증증거 항목을 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"AI 과업지시서·검수 기준 설계","common_error":"공급사 데모를 검수시험으로 대체","deliverable":"SOW·Acceptance Plan","check_question":"“공급사 데모를 검수시험으로 대체”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, AI 과업지시서·검수 기준 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 획득 시 데이터 권리·모델 변경·평가 데이터·공급망·유지보수·종속 위험을 계약과 연결한다.","misconception":"특정 도구의 기술 데모만으로 납품 검수를 대신하지 않는다."},{"id":"SP-009","name_ko":"AI 프로젝트 관리","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"WBS·마일스톤","objective":"실습 수행 목표 — 최소 3단계 WBS와 주요 마일스톤 4개를 만들고 산출물 수용기준을 연결하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"위험·이슈·변경","objective":"실습 수행 목표 — 위험 3건과 이슈 2건의 원인·영향·관리자·완화·승인 필요성을 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"이해관계자·보고","objective":"실습 수행 목표 — 회의보고서에 결론·이견·결정자·미결항목·다음 조치·기한을 정리하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"데이터·모델 의존성","objective":"실습 수행 목표 — 업무 선행관계 그래프를 만들고 핵심경로·병렬 가능한 작업·승인 대기를 식별하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"실험·품질 게이트","objective":"실습 수행 목표 — 데이터·모델·UI·보안 각 게이트의 입력·시험·판정자·실패 대응을 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"운영 인수인계","objective":"실습 수행 목표 — 운영 인수 체크리스트에 재해복구 연습·백업복원·보안승인·연락체계를 넣어라.","learning_cycle":"실무 산출물 평가"}],"lab":"12주 PoC WBS·위험대장 작성","common_error":"마일스톤만 있고 근거물이 없음","deliverable":"Project Plan","check_question":"“마일스톤만 있고 근거물이 없음”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 12주 PoC WBS·위험대장 작성을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 프로젝트 관리는 이해관계자·요구변경·위험·품질·책임·승인 게이트를 단계별로 연결한다.","misconception":"일정 진척률만으로 기술 위험이 줄어들었다고 판단하지 않는다."},{"id":"SP-010","name_ko":"AI TEV&V","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"시험·평가·검증·확인 구분","objective":"실습 수행 목표 — 네 용어에 대한 가상 시험항목 1개씩을 설계하고 결과 해석의 범위를 표시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"평가 시나리오·환경","objective":"실습 수행 목표 — 정상·경계·오류·보안 시나리오 각각 2건의 기대 결과와 판정방법을 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"지표·통계·불확실성","objective":"실습 수행 목표 — 정답표·표본 설계·혼동행렬·95% 불확실성 평가 방법과 판단 한계를 기술하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"강건성·오류주입","objective":"실습 수행 목표 — 합성 오류 5종을 주입하고 탐지·격리·복구·잔여 위험을 시험보고서에 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"안전·보안·인간 감독","objective":"실습 수행 목표 — 권한 거부·감사로그·인간 승인·긴급중단의 실패시험 4개를 설계하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"결과·수용·재시험","objective":"실습 수행 목표 — TEV&V 종료보고서에 실패목록·수정·재시험·미해결 위험·승인권자의 조건부 판단을 작성하라.","learning_cycle":"실무 산출물 평가"}],"lab":"성능·실패 조건 포함 TEV&V 설계","common_error":"평균 정확도만으로 합격","deliverable":"TEV&V Plan","check_question":"“평균 정확도만으로 합격”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 성능·실패 조건 포함 TEV&V 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"TEV&V는 시험(Test), 평가(Evaluation), 검증(Verification), 타당성확인(Validation)의 대상을 구분한다.","misconception":"개발 요구사항 충족이 사용자 목적 달성과 동일하지 않다."},{"id":"SP-011","name_ko":"책임 있는 AI","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"인간 중심·감독","objective":"실습 수행 목표 — AI 결과를 수락·수정·거부하는 흐름과 각각의 설명책임·오류 대응을 설계하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"편향·차별·안전","objective":"실습 수행 목표 — 그룹별 표본 수·성능 차이·원인 가설과 개선을 위한 추가 데이터 요구를 작성하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"설명·투명성·문서화","objective":"실습 수행 목표 — 사용자 설명 카드에 출처·버전·판단 한계·오류 신고 경로를 작성하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"오류·피해·책임","objective":"실습 수행 목표 — 오류 사건 보고서에 타임라인·영향·원인 가설·책임 검토·재발 방지를 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"허용사용범위","objective":"실습 수행 목표 — 모델 카드에 허용/금지 사용, 사용자 검토 의무, 위험한 오용 예시를 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"지속 모니터링","objective":"실습 수행 목표 — 월간 점검표에 드리프트·근거 일치·권한·신고·중단 기준을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"학습자 평가 AI의 편향 위험 분석","common_error":"모델 설명을 사실의 증명으로 오인","deliverable":"Responsible AI Assessment","check_question":"“모델 설명을 사실의 증명으로 오인”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 학습자 평가 AI의 편향 위험 분석을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"책임 있는 AI는 인간 감독, 투명성, 공정성, 개인정보, 안전과 책임 주체를 위험에 비례해 설계한다.","misconception":"원칙 선언이 실제 통제 시험을 대체하지 않는다."},{"id":"SP-012","name_ko":"AI 거버넌스","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"AI 자산·책임·승인","objective":"실습 수행 목표 — 자산등록부의 필수 필드와 변경 승인권자를 정의하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"위험분류·통제","objective":"실습 수행 목표 — 가상 사용사례 3개의 위험 평가 기준·통제·승인 수준을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"모델·데이터 버전","objective":"실습 수행 목표 — 변경 전후 영향 범위와 롤백 가능한 구성요소를 표로 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"권한·감사·모니터링","objective":"실습 수행 목표 — RBAC/ABAC 접근행렬과 계정회수·권한 거부 시험을 작성하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"사고·재평가·중단","objective":"실습 수행 목표 — 사고 대응 7단계와 보고·중단·재개 승인권자를 역할별로 지정하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"성과·내부통제","objective":"실습 수행 목표 — 분기 성과표의 KPI 5개와 내부감사 증거·미시정 위험을 연결하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"실무 산출물 평가"}],"lab":"가상 AI 모델 등록·승인 절차 설계","common_error":"제도상 권한 없는 담당자의 독자 승인","deliverable":"AI Governance Charter","check_question":"“제도상 권한 없는 담당자의 독자 승인”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 가상 AI 모델 등록·승인 절차 설계을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"AI 거버넌스는 모델·데이터·프로젝트 승인권한과 운영 중 위험·변경 통제를 연결한다.","misconception":"전문가 자문을 형식적 서명 절차로만 취급하지 않는다."},{"id":"SP-013","name_ko":"국방 AI 로드맵","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-001","SP-002"],"modules":[{"sequence":1,"title":"업무 목표·사업 포트폴리오","objective":"실습 수행 목표 — 2년 로드맵에 목표 KPI, 선행조건, 승인 게이트, 비용 가정을 표시하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"기술·데이터 선후관계","objective":"실습 수행 목표 — 데이터 통합과 AI 적용의 의존성 DAG를 작성하고 선행 조건 미달시 대안 경로를 설정하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"인력·교육·인프라","objective":"실습 수행 목표 — 역할별 현 역량·목표·필수 실습·백업 인력·운영 책임을 계획하라. 실행 조건·측정 대상·산출물 검증 기준을 함께 명시하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"예산·위험·의존성","objective":"실습 수행 목표 — 사업 간 자원경합·공통 위험·비용·승인대기 시간을 표시한 포트폴리오 계획을 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"단기·중기·장기 계획","objective":"실습 수행 목표 — 각 기간에 산출물·예산 범위·책임기관·선행조건·재검토 시점을 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"KPI·이행 재평가","objective":"실습 수행 목표 — 분기 재평가 회의표에 기준선·실제값·정의 변경·중단/확대/변경 결정 근거를 넣어라.","learning_cycle":"실무 산출물 평가"}],"lab":"공개·가상 사례 3단계 로드맵","common_error":"근거 없는 장비·사업 일정 단정","deliverable":"Roadmap·Portfolio","check_question":"“근거 없는 장비·사업 일정 단정”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, 공개·가상 사례 3단계 로드맵을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"로드맵은 역량·데이터·인프라·제도 선행조건을 기준으로 단계별 Go/No-Go를 정한다.","misconception":"시범사업 성공 없이 전면 확대 일정부터 확정하는 것은 위험하다."},{"id":"SP-014","name_ko":"통합 Capstone 사업주도","track":"SP","level":"Foundation-Advanced","prerequisites":["SP-002","SP-004","SP-005","SP-010"],"modules":[{"sequence":1,"title":"실제 문제정의 방법","objective":"실습 수행 목표 — 문제 정의서에 사용자·업무흐름·범위·성공기준·비AI 대안·승인경계를 작성하라.","learning_cycle":"핵심 개념과 공식·표준 검토"},{"sequence":2,"title":"기술·데이터 설계 결합","objective":"실습 수행 목표 — 수집·정제·접근통제·인용검증 파이프라인 아키텍처와 데이터 계약을 설계하라.","learning_cycle":"반례·오개념 판별"},{"sequence":3,"title":"인수·품질·보안 요구","objective":"실습 수행 목표 — 요구 추적행렬에 데이터 품질·RAG 근거·보안·접근성 수용항목과 시험계획을 연결하라.","learning_cycle":"합성 예제 적용"},{"sequence":4,"title":"예산·대안·위험","objective":"실습 수행 목표 — 세 대안의 기간별 비용·성능·법률·보안 위험, 민감도, 선정 근거를 작성하라.","learning_cycle":"근거와 한계 기록"},{"sequence":5,"title":"실증·검수·이행계획","objective":"실습 수행 목표 — 파일럿 범위·단계별 승인 조건·재시험 및 실제 사용자 교육계획을 작성하라.","learning_cycle":"결과 재현·동료 검토"},{"sequence":6,"title":"최종 독립 설계 방어","objective":"실습 수행 목표 — 10분 발표자료와 10분 질의응답을 준비하고 핵심 주장 5개에 증빙·반례·추가 검증 계획을 붙여라.","learning_cycle":"실무 산출물 평가"}],"lab":"AI 사업 종합제안·구술방어","common_error":"실증되지 않은 결과를 구축 완료로 표시","deliverable":"14항목 사업기획서·TEV&V","check_question":"“실증되지 않은 결과를 구축 완료로 표시”라는 주장이 왜 잘못될 수 있는가?","expected_answer":"해당 주장의 범위·가정·반례를 구분하고, AI 사업 종합제안·구술방어을(를) 이용하여 근거를 제시해야 한다.","references":["https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000276642","https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000280208","https://www.nist.gov/itl/ai-risk-management-framework"],"status":"CONTENT_DRAFT_NOT_APPROVED","insight":"통합 Capstone은 요구사항에서 시험 결과·비용·위험·운영·승인 판단까지 추적 가능한 포트폴리오다.","misconception":"구현하지 않은 기능을 성능 검증 완료로 주장하지 않는다."}]};